CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL,slug VARCHAR(100) UNIQUE NOT NULL,description VARCHAR(255) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) UNIQUE NOT NULL,slug VARCHAR(150) UNIQUE NOT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,email_verified_at TIMESTAMP NULL,password VARCHAR(255) NOT NULL,phone VARCHAR(40) NULL,avatar VARCHAR(500) NULL,status ENUM('active','inactive','invited') NOT NULL DEFAULT 'active',last_login_at TIMESTAMP NULL,remember_token VARCHAR(100) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE password_reset_tokens (email VARCHAR(190) PRIMARY KEY,token VARCHAR(255) NOT NULL,created_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,role_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE lead_sources (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(100) UNIQUE NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE lead_statuses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(100) UNIQUE NOT NULL,color VARCHAR(20) NULL,sort_order INT NOT NULL DEFAULT 0,is_closed BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE companies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,email VARCHAR(190) NULL,phone VARCHAR(40) NULL,website VARCHAR(255) NULL,address TEXT NULL,city VARCHAR(100) NULL,state VARCHAR(100) NULL,country VARCHAR(100) NULL,owner_id BIGINT UNSIGNED NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE contacts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NULL,owner_id BIGINT UNSIGNED NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NULL,email VARCHAR(190) NULL,phone VARCHAR(40) NULL,job_title VARCHAR(150) NULL,notes TEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,INDEX(email),INDEX(phone),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE SET NULL,FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE leads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NULL,contact_id BIGINT UNSIGNED NULL,assigned_to BIGINT UNSIGNED NULL,source_id BIGINT UNSIGNED NULL,status_id BIGINT UNSIGNED NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NULL,email VARCHAR(190) NULL,phone VARCHAR(40) NULL,title VARCHAR(190) NULL,value DECIMAL(15,2) NULL,currency CHAR(3) NOT NULL DEFAULT 'INR',source_reference VARCHAR(190) NULL,source_payload JSON NULL,last_contacted_at TIMESTAMP NULL,converted_at TIMESTAMP NULL,lost_reason VARCHAR(255) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,INDEX(email),INDEX(phone),INDEX(assigned_to),INDEX(source_id),INDEX(status_id),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE SET NULL,FOREIGN KEY(contact_id) REFERENCES contacts(id) ON DELETE SET NULL,FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(source_id) REFERENCES lead_sources(id) ON DELETE SET NULL,FOREIGN KEY(status_id) REFERENCES lead_statuses(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE tags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL,color VARCHAR(20) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE lead_tags (lead_id BIGINT UNSIGNED NOT NULL,tag_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(lead_id,tag_id),FOREIGN KEY(lead_id) REFERENCES leads(id) ON DELETE CASCADE,FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE lead_notes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lead_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,body TEXT NOT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(lead_id) REFERENCES leads(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE lead_activities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lead_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,type VARCHAR(80) NOT NULL,subject VARCHAR(190) NULL,body TEXT NULL,metadata JSON NULL,created_at TIMESTAMP NULL,FOREIGN KEY(lead_id) REFERENCES leads(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE pipelines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,is_default BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE pipeline_stages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,pipeline_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,sort_order INT NOT NULL DEFAULT 0,probability DECIMAL(5,2) NOT NULL DEFAULT 0,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(pipeline_id) REFERENCES pipelines(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE deals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,pipeline_id BIGINT UNSIGNED NOT NULL,stage_id BIGINT UNSIGNED NOT NULL,lead_id BIGINT UNSIGNED NULL,contact_id BIGINT UNSIGNED NULL,company_id BIGINT UNSIGNED NULL,owner_id BIGINT UNSIGNED NULL,title VARCHAR(190) NOT NULL,value DECIMAL(15,2) NOT NULL DEFAULT 0,currency CHAR(3) NOT NULL DEFAULT 'INR',expected_close_date DATE NULL,status ENUM('open','won','lost') NOT NULL DEFAULT 'open',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(pipeline_id) REFERENCES pipelines(id) ON DELETE RESTRICT,FOREIGN KEY(stage_id) REFERENCES pipeline_stages(id) ON DELETE RESTRICT,FOREIGN KEY(lead_id) REFERENCES leads(id) ON DELETE SET NULL,FOREIGN KEY(contact_id) REFERENCES contacts(id) ON DELETE SET NULL,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE SET NULL,FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,lead_id BIGINT UNSIGNED NULL,contact_id BIGINT UNSIGNED NULL,deal_id BIGINT UNSIGNED NULL,title VARCHAR(190) NOT NULL,description TEXT NULL,due_at TIMESTAMP NULL,priority ENUM('low','medium','high','urgent') NOT NULL DEFAULT 'medium',status ENUM('pending','completed','cancelled') NOT NULL DEFAULT 'pending',completed_at TIMESTAMP NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(lead_id) REFERENCES leads(id) ON DELETE CASCADE,FOREIGN KEY(contact_id) REFERENCES contacts(id) ON DELETE SET NULL,FOREIGN KEY(deal_id) REFERENCES deals(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,type VARCHAR(100) NOT NULL,title VARCHAR(190) NOT NULL,body TEXT NULL,data JSON NULL,read_at TIMESTAMP NULL,created_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(150) UNIQUE NOT NULL,setting_value JSON NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(100) NULL,entity_id BIGINT UNSIGNED NULL,old_values JSON NULL,new_values JSON NULL,ip_address VARCHAR(45) NULL,user_agent VARCHAR(500) NULL,created_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
